import{_ as s,l,o as r,c as n,v as t,p as i,x as e,d as h,i as c,S as u}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"Hasbrouck 报价-成交 VAR","description":"","frontmatter":{"title":"Hasbrouck 报价-成交 VAR","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hasbrouck-var.md","filePath":"quant/hasbrouck-var.md","lastUpdated":1789023840000}'),p={name:"quant/hasbrouck-var.md"};function d(_,a,A,b,m,E){const o=l("Mermaid");return r(),n("div",null,[a[1]||(a[1]=t('<h1 id="hasbrouck-报价-成交-var" tabindex="-1">Hasbrouck 报价-成交 VAR <a class="header-anchor" href="#hasbrouck-报价-成交-var" aria-label="Permalink to &quot;Hasbrouck 报价-成交 VAR&quot;">​</a></h1><div class="epigraph"><p>把成交与报价放进一个向量自回归：成交对后续报价的永久影响，度量这笔交易的信息含量；随后回复的部分，才是弹跳、库存与噪声。</p><footer>—— Hasbrouck, Measuring the Information Content of Stock Trades, Journal of Finance, 1991</footer></div><p><a href="/quant/stoll-three-components">Stoll 三成分</a>用成交指示回归给价差做会计。缺口是更一般的动态：报价与成交互相预测，冲击有脉冲响应，不必事先把移动贴成三个常数比例。Hasbrouck（1991）估计成交–报价的 VAR（及同年 RFS 的信息含量摘要），把一笔带符号成交的<strong>永久价格影响</strong>定义为信息含量。本课不是 <a href="/quant/hasbrouck-is">1995 年多市场信息份额</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Stoll 型回归把 \\(\\Delta m_t\\) 写成 \\(Q_{t-1}\\) 的同期函数，滞后结构很短。真实过程里，大单被拆开、报价在成交前已动、成交后还有多步修订。需要一个对 \\(\\{q_t,r_t\\}\\)（带符号成交与报价或中点收益）的线性动态，问：对 \\(q\\) 的一个新息，当 \\(h\\to\\infty\\) 时 \\(r\\) 的累积响应是多少。这个极限响应是交易的信息含量；有限 \\(h\\) 上多出来又缩回去的，是暂时成分。</p><p>问题还包括识别新息：当期成交与当期报价修订往往同时发生。Hasbrouck 用结构假设（例如成交可以立刻进报价，报价新息不立刻进成交，或反过来做稳健）来排因果顺序。顺序一错，永久影响会把弹跳算进去。</p><h3 id="与信息份额课的分工" tabindex="-1">与信息份额课的分工 <a class="header-anchor" href="#与信息份额课的分工" aria-label="Permalink to &quot;与信息份额课的分工&quot;">​</a></h3><p><a href="/quant/hasbrouck-is">信息份额</a>问多个市场谁对共同随机游走贡献方差。本课问<strong>同一市场</strong>里，交易相对于报价修订贡献了多少随机游走。一个是跨市场分解，一个是交易对报价的脉冲。Gonzalo–Granger 的永久成分是下一课的对象。</p><p><span class="marginnote">经验 Kyle \\(\\lambda\\) 常是 \\(\\Delta p\\) 对 \\(q\\) 的同期回归，相当于 VAR 脉冲的第 0 步。Hasbrouck 要的是脉冲的终点，不是第 0 步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>令 \\(x_t=(r_t,q_t)&#39;\\)，</p> \\[x_t = A_1 x_{t-1}+\\cdots+A_p x_{t-p}+\\varepsilon_t. \\]<p>\\(r_t\\) 多用中点对数变化，\\(q_t\\) 用带符号量或方向。成交新息的长期乘数</p> \\[\\alpha_q = \\lim_{h\\to\\infty} \\frac{\\partial}{\\partial \\varepsilon^q} \\sum_{k=0}^{h} r_{t+k} \\]<p>是信息含量。可对大单、小单、不同时段分别估。Hasbrouck（1991, RFS）还把信息含量收成 \\(R^2\\) 型摘要：随机游走新息方差里有多少能被交易解释。</p><h3 id="暂时成分是残差-不是「库存的名字」" tabindex="-1">暂时成分是残差，不是「库存的名字」 <a class="header-anchor" href="#暂时成分是残差-不是「库存的名字」" aria-label="Permalink to &quot;暂时成分是残差，不是「库存的名字」&quot;">​</a></h3><p>VAR 不先验标签库存或处理。凡是不进入随机游走的线性组合，都叫暂时。要说它是库存，需要额外把做市商头寸放进系统。本课的机制贡献是<strong>分离永久与暂时</strong>，而不是完成 Stoll 的三项命名。</p>',17)),(r(),i(u,null,{default:e(()=>[c(o,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E6%88%90%E4%BA%A4%E6%96%B0%E6%81%AF%20q%22%5D%20--%3E%20VAR%5B%22%E6%8A%A5%E4%BB%B7-%E6%88%90%E4%BA%A4%20VAR%22%5D%0A%20%20R%5B%22%E6%8A%A5%E4%BB%B7%E6%94%B6%E7%9B%8A%20r%22%5D%20--%3E%20VAR%0A%20%20VAR%20--%3E%20Perm%5B%22%E9%95%BF%E6%9C%9F%E4%B9%98%E6%95%B0%20%3D%20%E4%BF%A1%E6%81%AF%E5%90%AB%E9%87%8F%22%5D%0A%20%20VAR%20--%3E%20Trans%5B%22%E6%9C%89%E9%99%90%E6%AD%A5%E5%9B%9E%E5%A4%8D%20%3D%20%E6%9A%82%E6%97%B6%E6%88%90%E5%88%86%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公共信息可以先改报价、再诱发成交，也可以先成交、再改报价。VAR 允许两条通道。若市场有效且无微观结构摩擦，成交新息对价格的永久影响应等于其信息，暂时影响为零。摩擦把暂时影响做大：弹跳、库存、过时报价。信息含量随公司规模、价差、时段变化，给出「哪些交易在发现价格」的描述，而不需要 PIN 的体制结构。</p><p>与连续 Kyle 对照：那里全部价格移动都是对累计流的滤波，没有单独的报价过程。Hasbrouck 的数据是电子盘的报价与成交两条时间序列，更靠近<a href="/quant/lob-structure">限价簿</a>的可观测量。\\(\\alpha_q\\) 可以看成时变、状态依赖的经验 \\(\\lambda\\)，但不是均衡里的常数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>线性、平稳、新息顺序，三条都脆。跳变、隔夜、集合竞价要切开样本。多市场时本地 \\(q\\) 不是全部流，永久影响会被低估或错配，那是信息份额的问题。隐藏流动性让 \\(q\\) 测量不全。高频下微观结构噪声使 \\(r_t\\) 以负自相关为主，滞后阶数不足会把暂时当永久。</p><p><span class="marginnote">把 \\(\\alpha_q\\) 在截面上对预期收益回归，并不自动等于 Amihud–Mendelson。信息含量高可能意味着逆向选择溢价，也可能意味着更有效的发现、风险更低。符号不是理论定理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hasbrouck（1991）用报价–成交 VAR 把一笔交易的永久价格影响定义为信息含量。</li><li>同期回归斜率只是脉冲的第 0 步；终点乘数才对应随机游走。</li><li>暂时成分是不进入随机游走的部分，默认不贴库存标签。</li><li>1995 年信息份额是多市场问题，不在本课。</li><li>出处：Hasbrouck, <em>Journal of Finance</em>, 1991；摘要度量见 Hasbrouck, <em>Review of Financial Studies</em>, 1991。</li></ul>',8))])}const f=s(p,[["render",d]]);export{q as __pageData,f as default};
